# ! [doc = " Collection types."] # ! [doc = ""] # ! [doc = " Rust's standard collection library provides efficient implementations of the"] # ! [doc = " most common general purpose programming data structures. By using the"] # ! [doc = " standard implementations, it should be possible for two libraries to"] # ! [doc = " communicate without significant data conversion."] # ! [doc = ""] # ! [doc = " To get this out of the way: you should probably just use [`Vec`] or [`HashMap`]."] # ! [doc = " These two collections cover most use cases for generic data storage and"] # ! [doc = " processing. They are exceptionally good at doing what they do. All the other"] # ! [doc = " collections in the standard library have specific use cases where they are"] # ! [doc = " the optimal choice, but these cases are borderline *niche* in comparison."] # ! [doc = " Even when `Vec` and `HashMap` are technically suboptimal, they're probably a"] # ! [doc = " good enough choice to get started."] # ! [doc = ""] # ! [doc = " Rust's collections can be grouped into four major categories:"] # ! [doc = ""] # ! [doc = " * Sequences: [`Vec`], [`VecDeque`], [`LinkedList`]"] # ! [doc = " * Maps: [`HashMap`], [`BTreeMap`]"] # ! [doc = " * Sets: [`HashSet`], [`BTreeSet`]"] # ! [doc = " * Misc: [`BinaryHeap`]"] # ! [doc = ""] # ! [doc = " # When Should You Use Which Collection?"] # ! [doc = ""] # ! [doc = " These are fairly high-level and quick break-downs of when each collection"] # ! [doc = " should be considered. Detailed discussions of strengths and weaknesses of"] # ! [doc = " individual collections can be found on their own documentation pages."] # ! [doc = ""] # ! [doc = " ### Use a [`Vec`] when:"] # ! [doc = " * You want to collect items up to be processed or sent elsewhere later, and"] # ! [doc = "   don't care about any properties of the actual values being stored."] # ! [doc = " * You want a sequence of elements in a particular order, and will only be"] # ! [doc = "   appending to (or near) the end."] # ! [doc = " * You want a stack."] # ! [doc = " * You want a resizable array."] # ! [doc = " * You want a heap-allocated array."] # ! [doc = ""] # ! [doc = " ### Use a [`VecDeque`] when:"] # ! [doc = " * You want a [`Vec`] that supports efficient insertion at both ends of the"] # ! [doc = "   sequence."] # ! [doc = " * You want a queue."] # ! [doc = " * You want a double-ended queue (deque)."] # ! [doc = ""] # ! [doc = " ### Use a [`LinkedList`] when:"] # ! [doc = " * You want a [`Vec`] or [`VecDeque`] of unknown size, and can't tolerate"] # ! [doc = "   amortization."] # ! [doc = " * You want to efficiently split and append lists."] # ! [doc = " * You are *absolutely* certain you *really*, *truly*, want a doubly linked"] # ! [doc = "   list."] # ! [doc = ""] # ! [doc = " ### Use a [`HashMap`] when:"] # ! [doc = " * You want to associate arbitrary keys with an arbitrary value."] # ! [doc = " * You want a cache."] # ! [doc = " * You want a map, with no extra functionality."] # ! [doc = ""] # ! [doc = " ### Use a [`BTreeMap`] when:"] # ! [doc = " * You want a map sorted by its keys."] # ! [doc = " * You want to be able to get a range of entries on-demand."] # ! [doc = " * You're interested in what the smallest or largest key-value pair is."] # ! [doc = " * You want to find the largest or smallest key that is smaller or larger"] # ! [doc = "   than something."] # ! [doc = ""] # ! [doc = " ### Use the `Set` variant of any of these `Map`s when:"] # ! [doc = " * You just want to remember which keys you've seen."] # ! [doc = " * There is no meaningful value to associate with your keys."] # ! [doc = " * You just want a set."] # ! [doc = ""] # ! [doc = " ### Use a [`BinaryHeap`] when:"] # ! [doc = ""] # ! [doc = " * You want to store a bunch of elements, but only ever want to process the"] # ! [doc = "   \"biggest\" or \"most important\" one at any given time."] # ! [doc = " * You want a priority queue."] # ! [doc = ""] # ! [doc = " # Performance"] # ! [doc = ""] # ! [doc = " Choosing the right collection for the job requires an understanding of what"] # ! [doc = " each collection is good at. Here we briefly summarize the performance of"] # ! [doc = " different collections for certain important operations. For further details,"] # ! [doc = " see each type's documentation, and note that the names of actual methods may"] # ! [doc = " differ from the tables below on certain collections."] # ! [doc = ""] # ! [doc = " Throughout the documentation, we will adhere to the following conventions"] # ! [doc = " for operation notation:"] # ! [doc = ""] # ! [doc = " * The collection's size is denoted by `n`."] # ! [doc = " * If a second collection is involved, its size is denoted by `m`."] # ! [doc = " * Item indices are denoted by `i`."] # ! [doc = " * Operations which have an *amortized* cost are suffixed with a `*`."] # ! [doc = " * Operations with an *expected* cost are suffixed with a `~`."] # ! [doc = ""] # ! [doc = " Calling operations that add to a collection will occasionally require a"] # ! [doc = " collection to be resized - an extra operation that takes *O*(*n*) time."] # ! [doc = ""] # ! [doc = " *Amortized* costs are calculated to account for the time cost of such resize"] # ! [doc = " operations *over a sufficiently large series of operations*. An individual"] # ! [doc = " operation may be slower or faster due to the sporadic nature of collection"] # ! [doc = " resizing, however the average cost per operation will approach the amortized"] # ! [doc = " cost."] # ! [doc = ""] # ! [doc = " Rust's collections never automatically shrink, so removal operations aren't"] # ! [doc = " amortized."] # ! [doc = ""] # ! [doc = " [`HashMap`] uses *expected* costs. It is theoretically possible, though very"] # ! [doc = " unlikely, for [`HashMap`] to experience significantly worse performance than"] # ! [doc = " the expected cost. This is due to the probabilistic nature of hashing - i.e."] # ! [doc = " it is possible to generate a duplicate hash given some input key that will"] # ! [doc = " requires extra computation to correct."] # ! [doc = ""] # ! [doc = " ## Cost of Collection Operations"] # ! [doc = ""] # ! [doc = ""] # ! [doc = " |                | get(i)                 | insert(i)               | remove(i)              | append(Vec(m))    | split_off(i)           | range           | append       |"] # ! [doc = " |----------------|------------------------|-------------------------|------------------------|-------------------|------------------------|-----------------|--------------|"] # ! [doc = " | [`Vec`]        | *O*(1)                 | *O*(*n*-*i*)*           | *O*(*n*-*i*)           | *O*(*m*)*         | *O*(*n*-*i*)           | N/A             | N/A          |"] # ! [doc = " | [`VecDeque`]   | *O*(1)                 | *O*(min(*i*, *n*-*i*))* | *O*(min(*i*, *n*-*i*)) | *O*(*m*)*         | *O*(min(*i*, *n*-*i*)) | N/A             | N/A          |"] # ! [doc = " | [`LinkedList`] | *O*(min(*i*, *n*-*i*)) | *O*(min(*i*, *n*-*i*))  | *O*(min(*i*, *n*-*i*)) | *O*(1)            | *O*(min(*i*, *n*-*i*)) | N/A             | N/A          |"] # ! [doc = " | [`HashMap`]    | *O*(1)~                | *O*(1)~*                | *O*(1)~                | N/A               | N/A                    | N/A             | N/A          |"] # ! [doc = " | [`BTreeMap`]   | *O*(log(*n*))          | *O*(log(*n*))           | *O*(log(*n*))          | N/A               | N/A                    | *O*(log(*n*))   | *O*(*n*+*m*) |"] # ! [doc = ""] # ! [doc = " Note that where ties occur, [`Vec`] is generally going to be faster than"] # ! [doc = " [`VecDeque`], and [`VecDeque`] is generally going to be faster than"] # ! [doc = " [`LinkedList`]."] # ! [doc = ""] # ! [doc = " For Sets, all operations have the cost of the equivalent Map operation."] # ! [doc = ""] # ! [doc = " # Correct and Efficient Usage of Collections"] # ! [doc = ""] # ! [doc = " Of course, knowing which collection is the right one for the job doesn't"] # ! [doc = " instantly permit you to use it correctly. Here are some quick tips for"] # ! [doc = " efficient and correct usage of the standard collections in general. If"] # ! [doc = " you're interested in how to use a specific collection in particular, consult"] # ! [doc = " its documentation for detailed discussion and code examples."] # ! [doc = ""] # ! [doc = " ## Capacity Management"] # ! [doc = ""] # ! [doc = " Many collections provide several constructors and methods that refer to"] # ! [doc = " \"capacity\". These collections are generally built on top of an array."] # ! [doc = " Optimally, this array would be exactly the right size to fit only the"] # ! [doc = " elements stored in the collection, but for the collection to do this would"] # ! [doc = " be very inefficient. If the backing array was exactly the right size at all"] # ! [doc = " times, then every time an element is inserted, the collection would have to"] # ! [doc = " grow the array to fit it. Due to the way memory is allocated and managed on"] # ! [doc = " most computers, this would almost surely require allocating an entirely new"] # ! [doc = " array and copying every single element from the old one into the new one."] # ! [doc = " Hopefully you can see that this wouldn't be very efficient to do on every"] # ! [doc = " operation."] # ! [doc = ""] # ! [doc = " Most collections therefore use an *amortized* allocation strategy. They"] # ! [doc = " generally let themselves have a fair amount of unoccupied space so that they"] # ! [doc = " only have to grow on occasion. When they do grow, they allocate a"] # ! [doc = " substantially larger array to move the elements into so that it will take a"] # ! [doc = " while for another grow to be required. While this strategy is great in"] # ! [doc = " general, it would be even better if the collection *never* had to resize its"] # ! [doc = " backing array. Unfortunately, the collection itself doesn't have enough"] # ! [doc = " information to do this itself. Therefore, it is up to us programmers to give"] # ! [doc = " it hints."] # ! [doc = ""] # ! [doc = " Any `with_capacity` constructor will instruct the collection to allocate"] # ! [doc = " enough space for the specified number of elements. Ideally this will be for"] # ! [doc = " exactly that many elements, but some implementation details may prevent"] # ! [doc = " this. See collection-specific documentation for details. In general, use"] # ! [doc = " `with_capacity` when you know exactly how many elements will be inserted, or"] # ! [doc = " at least have a reasonable upper-bound on that number."] # ! [doc = ""] # ! [doc = " When anticipating a large influx of elements, the `reserve` family of"] # ! [doc = " methods can be used to hint to the collection how much room it should make"] # ! [doc = " for the coming items. As with `with_capacity`, the precise behavior of"] # ! [doc = " these methods will be specific to the collection of interest."] # ! [doc = ""] # ! [doc = " For optimal performance, collections will generally avoid shrinking"] # ! [doc = " themselves. If you believe that a collection will not soon contain any more"] # ! [doc = " elements, or just really need the memory, the `shrink_to_fit` method prompts"] # ! [doc = " the collection to shrink the backing array to the minimum size capable of"] # ! [doc = " holding its elements."] # ! [doc = ""] # ! [doc = " Finally, if ever you're interested in what the actual capacity of the"] # ! [doc = " collection is, most collections provide a `capacity` method to query this"] # ! [doc = " information on demand. This can be useful for debugging purposes, or for"] # ! [doc = " use with the `reserve` methods."] # ! [doc = ""] # ! [doc = " ## Iterators"] # ! [doc = ""] # ! [doc = " [Iterators][crate::iter]"] # ! [doc = " are a powerful and robust mechanism used throughout Rust's"] # ! [doc = " standard libraries. Iterators provide a sequence of values in a generic,"] # ! [doc = " safe, efficient and convenient way. The contents of an iterator are usually"] # ! [doc = " *lazily* evaluated, so that only the values that are actually needed are"] # ! [doc = " ever actually produced, and no allocation need be done to temporarily store"] # ! [doc = " them. Iterators are primarily consumed using a `for` loop, although many"] # ! [doc = " functions also take iterators where a collection or sequence of values is"] # ! [doc = " desired."] # ! [doc = ""] # ! [doc = " All of the standard collections provide several iterators for performing"] # ! [doc = " bulk manipulation of their contents. The three primary iterators almost"] # ! [doc = " every collection should provide are `iter`, `iter_mut`, and `into_iter`."] # ! [doc = " Some of these are not provided on collections where it would be unsound or"] # ! [doc = " unreasonable to provide them."] # ! [doc = ""] # ! [doc = " `iter` provides an iterator of immutable references to all the contents of a"] # ! [doc = " collection in the most \"natural\" order. For sequence collections like [`Vec`],"] # ! [doc = " this means the items will be yielded in increasing order of index starting"] # ! [doc = " at 0. For ordered collections like [`BTreeMap`], this means that the items"] # ! [doc = " will be yielded in sorted order. For unordered collections like [`HashMap`],"] # ! [doc = " the items will be yielded in whatever order the internal representation made"] # ! [doc = " most convenient. This is great for reading through all the contents of the"] # ! [doc = " collection."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " let vec = vec![1, 2, 3, 4];"] # ! [doc = " for x in vec.iter() {"] # ! [doc = "    println!(\"vec contained {x:?}\");"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " `iter_mut` provides an iterator of *mutable* references in the same order as"] # ! [doc = " `iter`. This is great for mutating all the contents of the collection."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " let mut vec = vec![1, 2, 3, 4];"] # ! [doc = " for x in vec.iter_mut() {"] # ! [doc = "    *x += 1;"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " `into_iter` transforms the actual collection into an iterator over its"] # ! [doc = " contents by-value. This is great when the collection itself is no longer"] # ! [doc = " needed, and the values are needed elsewhere. Using `extend` with `into_iter`"] # ! [doc = " is the main way that contents of one collection are moved into another."] # ! [doc = " `extend` automatically calls `into_iter`, and takes any <code>T: [IntoIterator]</code>."] # ! [doc = " Calling `collect` on an iterator itself is also a great way to convert one"] # ! [doc = " collection into another. Both of these methods should internally use the"] # ! [doc = " capacity management tools discussed in the previous section to do this as"] # ! [doc = " efficiently as possible."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " let mut vec1 = vec![1, 2, 3, 4];"] # ! [doc = " let vec2 = vec![10, 20, 30, 40];"] # ! [doc = " vec1.extend(vec2);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " use std::collections::VecDeque;"] # ! [doc = ""] # ! [doc = " let vec = [1, 2, 3, 4];"] # ! [doc = " let buf: VecDeque<_> = vec.into_iter().collect();"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Iterators also provide a series of *adapter* methods for performing common"] # ! [doc = " threads to sequences. Among the adapters are functional favorites like `map`,"] # ! [doc = " `fold`, `skip` and `take`. Of particular interest to collections is the"] # ! [doc = " `rev` adapter, which reverses any iterator that supports this operation. Most"] # ! [doc = " collections provide reversible iterators as the way to iterate over them in"] # ! [doc = " reverse order."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " let vec = vec![1, 2, 3, 4];"] # ! [doc = " for x in vec.iter().rev() {"] # ! [doc = "    println!(\"vec contained {x:?}\");"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Several other collection methods also return iterators to yield a sequence"] # ! [doc = " of results but avoid allocating an entire collection to store the result in."] # ! [doc = " This provides maximum flexibility as"] # ! [doc = " [`collect`][crate::iter::Iterator::collect] or"] # ! [doc = " [`extend`][crate::iter::Extend::extend] can be called to"] # ! [doc = " \"pipe\" the sequence into any collection if desired. Otherwise, the sequence"] # ! [doc = " can be looped over with a `for` loop. The iterator can also be discarded"] # ! [doc = " after partial use, preventing the computation of the unused items."] # ! [doc = ""] # ! [doc = " ## Entries"] # ! [doc = ""] # ! [doc = " The `entry` API is intended to provide an efficient mechanism for"] # ! [doc = " manipulating the contents of a map conditionally on the presence of a key or"] # ! [doc = " not. The primary motivating use case for this is to provide efficient"] # ! [doc = " accumulator maps. For instance, if one wishes to maintain a count of the"] # ! [doc = " number of times each key has been seen, they will have to perform some"] # ! [doc = " conditional logic on whether this is the first time the key has been seen or"] # ! [doc = " not. Normally, this would require a `find` followed by an `insert`,"] # ! [doc = " effectively duplicating the search effort on each insertion."] # ! [doc = ""] # ! [doc = " When a user calls `map.entry(key)`, the map will search for the key and"] # ! [doc = " then yield a variant of the `Entry` enum."] # ! [doc = ""] # ! [doc = " If a `Vacant(entry)` is yielded, then the key *was not* found. In this case"] # ! [doc = " the only valid operation is to `insert` a value into the entry. When this is"] # ! [doc = " done, the vacant entry is consumed and converted into a mutable reference to"] # ! [doc = " the value that was inserted. This allows for further manipulation of the"] # ! [doc = " value beyond the lifetime of the search itself. This is useful if complex"] # ! [doc = " logic needs to be performed on the value regardless of whether the value was"] # ! [doc = " just inserted."] # ! [doc = ""] # ! [doc = " If an `Occupied(entry)` is yielded, then the key *was* found. In this case,"] # ! [doc = " the user has several options: they can `get`, `insert` or `remove` the"] # ! [doc = " value of the occupied entry. Additionally, they can convert the occupied"] # ! [doc = " entry into a mutable reference to its value, providing symmetry to the"] # ! [doc = " vacant `insert` case."] # ! [doc = ""] # ! [doc = " ### Examples"] # ! [doc = ""] # ! [doc = " Here are the two primary ways in which `entry` is used. First, a simple"] # ! [doc = " example where the logic performed on the values is trivial."] # ! [doc = ""] # ! [doc = " #### Counting the number of times each character in a string occurs"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " use std::collections::btree_map::BTreeMap;"] # ! [doc = ""] # ! [doc = " let mut count = BTreeMap::new();"] # ! [doc = " let message = \"she sells sea shells by the sea shore\";"] # ! [doc = ""] # ! [doc = " for c in message.chars() {"] # ! [doc = "     *count.entry(c).or_insert(0) += 1;"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " assert_eq!(count.get(&'s'), Some(&8));"] # ! [doc = ""] # ! [doc = " println!(\"Number of occurrences of each character\");"] # ! [doc = " for (char, count) in &count {"] # ! [doc = "     println!(\"{char}: {count}\");"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " When the logic to be performed on the value is more complex, we may simply"] # ! [doc = " use the `entry` API to ensure that the value is initialized and perform the"] # ! [doc = " logic afterwards."] # ! [doc = ""] # ! [doc = " #### Tracking the inebriation of customers at a bar"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " use std::collections::btree_map::BTreeMap;"] # ! [doc = ""] # ! [doc = " // A client of the bar. They have a blood alcohol level."] # ! [doc = " struct Person { blood_alcohol: f32 }"] # ! [doc = ""] # ! [doc = " // All the orders made to the bar, by client ID."] # ! [doc = " let orders = vec![1, 2, 1, 2, 3, 4, 1, 2, 2, 3, 4, 1, 1, 1];"] # ! [doc = ""] # ! [doc = " // Our clients."] # ! [doc = " let mut blood_alcohol = BTreeMap::new();"] # ! [doc = ""] # ! [doc = " for id in orders {"] # ! [doc = "     // If this is the first time we've seen this customer, initialize them"] # ! [doc = "     // with no blood alcohol. Otherwise, just retrieve them."] # ! [doc = "     let person = blood_alcohol.entry(id).or_insert(Person { blood_alcohol: 0.0 });"] # ! [doc = ""] # ! [doc = "     // Reduce their blood alcohol level. It takes time to order and drink a beer!"] # ! [doc = "     person.blood_alcohol *= 0.9;"] # ! [doc = ""] # ! [doc = "     // Check if they're sober enough to have another beer."] # ! [doc = "     if person.blood_alcohol > 0.3 {"] # ! [doc = "         // Too drunk... for now."] # ! [doc = "         println!(\"Sorry {id}, I have to cut you off\");"] # ! [doc = "     } else {"] # ! [doc = "         // Have another!"] # ! [doc = "         person.blood_alcohol += 0.1;"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # Insert and complex keys"] # ! [doc = ""] # ! [doc = " If we have a more complex key, calls to `insert` will"] # ! [doc = " not update the value of the key. For example:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " use std::cmp::Ordering;"] # ! [doc = " use std::collections::BTreeMap;"] # ! [doc = " use std::hash::{Hash, Hasher};"] # ! [doc = ""] # ! [doc = " #[derive(Debug)]"] # ! [doc = " struct Foo {"] # ! [doc = "     a: u32,"] # ! [doc = "     b: &'static str,"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " // we will compare `Foo`s by their `a` value only."] # ! [doc = " impl PartialEq for Foo {"] # ! [doc = "     fn eq(&self, other: &Self) -> bool { self.a == other.a }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl Eq for Foo {}"] # ! [doc = ""] # ! [doc = " // we will hash `Foo`s by their `a` value only."] # ! [doc = " impl Hash for Foo {"] # ! [doc = "     fn hash<H: Hasher>(&self, h: &mut H) { self.a.hash(h); }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl PartialOrd for Foo {"] # ! [doc = "     fn partial_cmp(&self, other: &Self) -> Option<Ordering> { self.a.partial_cmp(&other.a) }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl Ord for Foo {"] # ! [doc = "     fn cmp(&self, other: &Self) -> Ordering { self.a.cmp(&other.a) }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " let mut map = BTreeMap::new();"] # ! [doc = " map.insert(Foo { a: 1, b: \"baz\" }, 99);"] # ! [doc = ""] # ! [doc = " // We already have a Foo with an a of 1, so this will be updating the value."] # ! [doc = " map.insert(Foo { a: 1, b: \"xyz\" }, 100);"] # ! [doc = ""] # ! [doc = " // The value has been updated..."] # ! [doc = " assert_eq!(map.values().next().unwrap(), &100);"] # ! [doc = ""] # ! [doc = " // ...but the key hasn't changed. b is still \"baz\", not \"xyz\"."] # ! [doc = " assert_eq!(map.keys().next().unwrap().b, \"baz\");"] # ! [doc = " ```"] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; #[stable (feature = "try_reserve" , since = "1.57.0")] pub use alloc_crate :: collections :: TryReserveError ; #[unstable (feature = "try_reserve_kind" , reason = "Uncertain how much info should be exposed" , issue = "48043")] pub use alloc_crate :: collections :: TryReserveErrorKind ; #[stable (feature = "rust1" , since = "1.0.0")] pub use alloc_crate :: collections :: { BTreeMap , BTreeSet , BinaryHeap } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use alloc_crate :: collections :: { LinkedList , VecDeque } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use alloc_crate :: collections :: { binary_heap , btree_map , btree_set } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use alloc_crate :: collections :: { linked_list , vec_deque } ; #[stable (feature = "rust1" , since = "1.0.0")] #[doc (inline)] pub use self :: hash_map :: HashMap ; #[stable (feature = "rust1" , since = "1.0.0")] #[doc (inline)] pub use self :: hash_set :: HashSet ; #[stable (feature = "rust1" , since = "1.0.0")] #[deprecated (note = "moved to `std::ops::Bound`" , since = "1.26.0")] #[doc (hidden)] pub use crate :: ops :: Bound ; mod hash ; #[stable (feature = "rust1" , since = "1.0.0")] pub mod hash_map { # ! [doc = " A hash map implemented with quadratic probing and SIMD lookup."] #[stable (feature = "rust1" , since = "1.0.0")] pub use super :: hash :: map :: * ; #[stable (feature = "hashmap_build_hasher" , since = "1.7.0")] pub use crate :: hash :: random :: DefaultHasher ; #[stable (feature = "hashmap_build_hasher" , since = "1.7.0")] pub use crate :: hash :: random :: RandomState ; } #[stable (feature = "rust1" , since = "1.0.0")] pub mod hash_set { # ! [doc = " A hash set implemented as a `HashMap` where the value is `()`."] #[stable (feature = "rust1" , since = "1.0.0")] pub use super :: hash :: set :: * ; }